import { services } from "../data/portfolio";
import { useScrollReveal } from "../hooks/useScrollReveal";
import { useTheme } from "../context/ThemeContext";

export default function Services() {
  const { ref, revealed } = useScrollReveal();
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <section id="services" className={`py-28 border-t transition-colors duration-300
      ${isDark ? "bg-ink-900 border-wire" : "bg-paper-100 border-wire-light"}`}>
      <div className="max-w-6xl mx-auto px-6">
        <div className="mb-14">
          <p className="section-label mb-4">Services</p>
          <h2 className={`section-title text-3xl sm:text-4xl lg:text-5xl max-w-xl ${isDark ? "text-stone-200" : "text-gray-900"}`}>
            What I build<br />
            <span className={isDark ? "text-stone-500" : "text-gray-400"}>for your business.</span>
          </h2>
        </div>

        <div ref={ref} className={`${revealed ? "fade-up visible" : "fade-up"} grid md:grid-cols-3 gap-px ${isDark ? "bg-wire" : "bg-wire-light"}`}>
          {services.map((service) => (
            <div
              key={service.id}
              className={`p-8 group transition-colors duration-300
                ${isDark ? "bg-ink-900 hover:bg-ink-800" : "bg-paper-100 hover:bg-white"}`}
            >
              <div className="flex items-start justify-between mb-6">
                <span className={`font-mono text-xs tracking-widest ${isDark ? "text-stone-600" : "text-gray-400"}`}>
                  {service.id}
                </span>
                <span className="text-accent-glow opacity-0 group-hover:opacity-100 transition-opacity font-mono text-xs">↗</span>
              </div>
              <h3 className={`font-display font-bold text-lg mb-4 leading-snug ${isDark ? "text-stone-200" : "text-gray-900"}`}>
                {service.title}
              </h3>
              <p className={`text-sm leading-relaxed mb-8 ${isDark ? "text-stone-400" : "text-gray-600"}`}>
                {service.description}
              </p>
              <ul className="space-y-2.5">
                {service.items.map((item) => (
                  <li key={item} className={`flex items-start gap-2.5 text-sm ${isDark ? "text-stone-500" : "text-gray-500"}`}>
                    <span className="text-accent-glow mt-1 text-xs">—</span>
                    {item}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
